    ".github/workflows/ci-pr.yml": "# ci-pr: chạy trên mỗi PR nhắm vào main. 4 job độc lập, chạy song song.
# - backend-test: 447 unit test + AigameBackendApplicationTests (khởi động thật, chạy Flyway trên Supabase thật
#   của dự án — cần 5 secret bên dưới) + JaCoCo (chặn nếu LINE coverage < 70%, xem backend/pom.xml).
# - frontend-build: lint (oxlint) + test (Vitest) + build (gồm type-check TypeScript).
# - secret-scan: Gitleaks quét toàn bộ diff của PR, tìm secret bị commit nhầm.
# - docs-scripts: log AI không quá dài (xoay vòng bằng scripts/ai-log/rotate.mjs) và docs/openapi/INDEX.md còn mới.
#
# Còn thiếu so với sơ đồ CI/CD gốc (để làm sau, cần thêm tài khoản/hạ tầng):
# - SonarCloud (cần tài khoản) — khi có, gộp luôn phần "lint backend" vào đó.
# - Docker build, deploy staging/production — chưa có Dockerfile, chưa có server staging/production.

name: ci-pr

on:
  pull_request:
    branches: [main]

jobs:
  backend-test:
    name: Backend test (JDK 21)
    runs-on: ubuntu-latest
    defaults:
      run:
        working-directory: backend
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-java@v4
        with:
          distribution: temurin
          java-version: "21"
          cache: maven

      - name: Run tests (unit test + Layer 1-3 + khởi động thật trên Supabase)
        env:
          DB_URL: ${{ secrets.DB_URL }}
          DB_USERNAME: ${{ secrets.DB_USERNAME }}
          DB_PASSWORD: ${{ secrets.DB_PASSWORD }}
          JWT_SECRET: ${{ secrets.JWT_SECRET }}
          OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}
          PR_AUTHOR: ${{ github.event.pull_request.user.login }}
        # PR của Dependabot không nhận Actions secret nên không kết nối được Supabase; chỉ bỏ test khởi động thật,
        # không thêm secret DB cho Dependabot vì code của gói bên thứ ba chạy trong job này.
        run: |
          if [ "$PR_AUTHOR" = "dependabot[bot]" ]; then
            ./mvnw --batch-mode test '-Dtest=!AigameBackendApplicationTests' -Dsurefire.failIfNoSpecifiedTests=false
          else
            ./mvnw --batch-mode test
          fi

      - name: Upload JaCoCo coverage report
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: jacoco-report
          path: backend/target/site/jacoco
          retention-days: 14

  frontend-build:
    name: Frontend lint & build
    runs-on: ubuntu-latest
    defaults:
      run:
        working-directory: frontend
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: "24.22.1"
          cache: npm
          cache-dependency-path: frontend/package-lock.json

      - run: npm ci
      - run: npm run lint
      # Chỉ trên CI: giới hạn số luồng vitest (máy chạy CI ít nhân nên nhiều luồng làm test thời gian chập chờn, xem mục Nợ và rủi ro trong "docs/wiki/Kế hoạch và việc còn lại.md").
      # Chạy cục bộ vẫn dùng mặc định của vite.config.ts.
      - run: npm run test -- --maxWorkers=2
      - run: npm run build

  docs-scripts:
    name: Log AI và chỉ mục OpenAPI
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: "24.22.1"

      # Lỗi ở đây nghĩa là quên chạy: node scripts/ai-log/rotate.mjs hoặc node scripts/openapi/build-index.mjs
      - run: node scripts/ai-log/rotate.mjs --check
      - run: node --test scripts/ai-log/rotate.test.mjs scripts/openapi/build-index.test.mjs

  secret-scan:
    name: Secret scan (Gitleaks)
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - uses: gitleaks/gitleaks-action@v2
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
",
    "backend/src/main/resources/application.yml": "spring:
  config:
    import: optional:file:./.env[.properties]
  application:
    name: aigame-backend

  datasource:
    # Supabase (managed PostgreSQL) — use Session Pooler or Direct Connection.
    # Do NOT use the Transaction Pooler (port 6543): it is not compatible with
    # Hibernate's prepared statement caching.
    url: ${DB_URL}
    username: ${DB_USERNAME}
    password: ${DB_PASSWORD}
    hikari:
      # Supabase free tier caps concurrent connections, keep the pool small.
      maximum-pool-size: 5
      # Supabase installs pgvector in the extensions schema; LangChain4j needs it on the search path.
      connection-init-sql: SET search_path TO public, extensions
      data-source-properties:
        # Driver gộp các lệnh insert cùng loại trong một lô thành một câu multi-row: ít lượt đi về Supabase hơn.
        reWriteBatchedInserts: true

  jpa:
    hibernate:
      # Schema is managed by Flyway, never let Hibernate auto-generate DDL.
      ddl-auto: validate
    properties:
      hibernate:
        dialect: org.hibernate.dialect.PostgreSQLDialect
        # Mỗi lượt đi về Supabase mất hàng trăm ms: lưu một game (xóa rồi ghi lại mọi câu, bảng JOINED, danh sách lựa chọn) từng
        # tốn khoảng 100 câu lệnh lẻ. Gộp insert/update/delete theo lô và đọc các danh sách con theo lô thay vì từng câu một.
        jdbc:
          batch_size: 50
        order_inserts: true
        order_updates: true
        default_batch_fetch_size: 50
    open-in-view: false

  flyway:
    enabled: true
    locations: classpath:db/migration
    # Supabase's "public" schema is never empty, so Flyway needs a baseline.
    # baseline-version 0 makes sure V1 and V2 are still applied.
    baseline-on-migrate: true
    baseline-version: 0

server:
  port: ${SERVER_PORT:8080}

# Swagger UI (/swagger-ui.html) và spec sinh từ controller (/v3/api-docs). Mặc định bật để dev xem;
# môi trường triển khai thật đặt SWAGGER_ENABLED=false.
springdoc:
  api-docs:
    enabled: ${SWAGGER_ENABLED:true}
  swagger-ui:
    enabled: ${SWAGGER_ENABLED:true}
    operations-sorter: method

app:
  cors:
    allowed-origins: http://localhost:5173
  jwt:
    # HS256 signing key, at least 32 bytes. Provide it via the JWT_SECRET environment variable.
    secret: ${JWT_SECRET}
    access-token-ttl-minutes: 15
    refresh-token-ttl-hours: 24
  auth:
    refresh-cookie:
      name: refresh_token
      path: /api/auth
      same-site: Strict
      # Secure cookies need HTTPS in production; browsers still accept them on http://localhost.
      secure: ${COOKIE_SECURE:true}
  assets:
    # Thử nghiệm: chữ nói tới hình A mà gắn hình B thì báo lỗi Layer 2 để AI sinh lại (retrieval + luật).
    meaning-check:
      enabled: ${ASSET_MEANING_CHECK_ENABLED:false}
    # Thử nghiệm: đưa các hình có từ khóa trong yêu cầu lên đầu danh mục trong prompt.
    shortlist:
      enabled: ${ASSET_SHORTLIST_ENABLED:false}
  moderation:
    # Mặc định true: app từ chối khởi động nếu chưa có OPENAI_API_KEY, để không lỡ chạy với kiểm duyệt yếu.
    # Chỉ đặt MODERATION_REQUIRED=false khi chạy thử ở máy cá nhân (khi đó chỉ dùng danh sách từ cấm).
    required: ${MODERATION_REQUIRED:true}
    blocked-words-location: classpath:moderation/blocked-words-vi.txt
    openai:
      base-url: https://api.openai.com
      api-key: ${OPENAI_API_KEY:}
      model: omni-moderation-latest
      timeout-seconds: 10
  ai:
    gemini:
      api-key: ${GEMINI_API_KEY:}
      model: ${GEMINI_MODEL:gemini-3-flash-preview}
      game-generation:
        enabled: ${GEMINI_GAME_GENERATION_ENABLED:false}
  generation:
    # Rà chính tả bằng AI sau khi sinh game: thêm tới 2 lần gọi Gemini mỗi game (tốn hạn mức theo ngày của gói Gemini), nên tắt mặc định.
    wording-review:
      enabled: ${WORDING_REVIEW_ENABLED:false}
  curriculum-rag:
    constraints-approved-sha256: ${CURRICULUM_CONSTRAINTS_APPROVED_SHA256:}
    enabled: ${CURRICULUM_RAG_ENABLED:false}
    embedding-model: ${GEMINI_EMBEDDING_MODEL:gemini-embedding-001}
    # Candidate floor for the deterministic Math Grade 1 path only; never a semantic acceptance gate.
    min-score: ${CURRICULUM_RAG_MIN_SCORE:0.855}
    kindergarten:
      # Legacy ranking knobs retained for offline spike compatibility. Semantic runtime examines the
      # whole selected age/domain corpus; its evidence decision does not use this similarity threshold.
      top-k: ${CURRICULUM_KINDERGARTEN_TOP_K:8}
      min-score: ${CURRICULUM_KINDERGARTEN_MIN_SCORE:0.84}
