import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * Kiểm an toàn cho một danh sách đoạn chữ (Layer 3): danh sách từ cấm trước, sạch mới gửi một lần lên OpenAI Moderation.
 * Dùng chung cho chuỗi kiểm duyệt DSL ({@link SafetyGameValidator}) và CPF; mỗi chuỗi tự quyết lấy đoạn chữ nào.
 * Thiếu OPENAI_API_KEY mà {@code app.moderation.required=true} thì ứng dụng không khởi động (một chỗ cho cả hai chuỗi).
 */
@Slf4j
@Component
public class ContentSafetyCheck {

    static final String UNSAFE_MESSAGE = "Nội dung không phù hợp với trẻ em";
    static final String UNAVAILABLE_MESSAGE = "Không kiểm tra được độ an toàn của nội dung, vui lòng thử lại sau";

    private final BlockedWordList blockedWords;
    private final ContentModerationClient moderationClient;

    public ContentSafetyCheck(BlockedWordList blockedWords, ContentModerationClient moderationClient,
            @Value("${app.moderation.required:true}") boolean moderationRequired) {
        this.blockedWords = blockedWords;
        this.moderationClient = moderationClient;
        if (!moderationClient.isConfigured()) {
            if (moderationRequired) {
                throw new IllegalStateException(
                        "app.moderation.required=true nhưng chưa cấu hình OPENAI_API_KEY cho kiểm duyệt nội dung");
            }
            log.warn("Chưa cấu hình OPENAI_API_KEY: Layer 3 chỉ dùng danh sách từ cấm, KHÔNG gọi OpenAI Moderation");
        }
    }

    public List<ValidationError> check(List<TextEntry> texts) {
        List<ValidationError> blocked = new ArrayList<>();
        for (TextEntry entry : texts) {
            if (blockedWords.findIn(entry.text()).isPresent()) {
                blocked.add(new ValidationError(entry.path(), UNSAFE_MESSAGE, ValidationError.Kind.UNSAFE));
            }
        }
        if (!blocked.isEmpty() || texts.isEmpty() || !moderationClient.isConfigured()) {
            return blocked;
        }

        List<ModerationResult> results;
        try {
            results = moderationClient.moderate(texts.stream().map(TextEntry::text).toList());
        } catch (ModerationUnavailableException e) {
            log.error("Không kiểm tra được độ an toàn: {}", e.getMessage());
            return List.of(new ValidationError("$", UNAVAILABLE_MESSAGE, ValidationError.Kind.UNAVAILABLE));
        }

        // Thiếu kết quả nghĩa là có đoạn chưa được kiểm tra: không được coi là an toàn.
        if (results.size() != texts.size()) {
            log.error("Số kết quả kiểm duyệt ({}) khác số đoạn văn ({})", results.size(), texts.size());
            return List.of(new ValidationError("$", UNAVAILABLE_MESSAGE, ValidationError.Kind.UNAVAILABLE));
        }

        List<ValidationError> flagged = new ArrayList<>();
        for (int i = 0; i < results.size(); i++) {
            ModerationResult result = results.get(i);
            if (result.flagged()) {
                flagged.add(new ValidationError(texts.get(i).path(),
                        UNSAFE_MESSAGE + " (" + String.join(", ", result.categories()) + ")", ValidationError.Kind.UNSAFE));
            }
        }
        return flagged;
    }
}
"
  }
}

// Hook PreToolUse (Bash) của Claude Code: chặn `node -e`/`node --eval` có code nhiều dòng hoặc dài > 200 ký tự.
// Lý do: sinh code qua `node -e` trong bash đã làm mất một lớp escape 3 lần (docs/corrections.md); ghi ra file thì không.
// Nhận JSON của hook trên stdin, in quyết định deny ra stdout; lệnh khác thì im lặng cho qua.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const MAX_INLINE = 200;
export const MESSAGE = "Hãy ghi script vào một file .mjs trong scripts/tmp/ rồi chạy file đó";
// `node` hoặc `node.exe` đứng đầu lệnh hoặc sau khoảng trắng, ; & | (. Không có lượng từ lồng nhau: bản regex cũ gộp cả
// phần tuỳ chọn vào một regex bị CodeQL báo backtrack theo hàm mũ (ReDoS), nên phần tuỳ chọn duyệt bằng vòng lặp.
const NODE = /(?:^|[\s;&|(])node(?:\.exe)?(?=\s)/g;
const isSpace = (ch) => ch === " " || ch === "\t" || ch === "\n" || ch === "\r";

const tooLong = (code) => code.includes("\n") || code.length > MAX_INLINE;

// Đọc một đối số shell bắt đầu ở i: trong nháy đơn, trong nháy kép (bỏ qua ký tự sau `\`), hoặc tới khoảng trắng.
// Chỉ đo đúng đối số code, nên chữ `node -e` nằm trong lời văn (ví dụ heredoc của `git commit -m`) không bị chặn.
function readWord(text, i) {
  const quote = text[i];
  if (quote === "'" || quote === '"') {
    let j = i + 1;
    while (j < text.length && text[j] !== quote) j += quote === '"' && text[j] === "\\" ? 2 : 1;
    return { code: text.slice(i + 1, j), end: Math.min(j + 1, text.length) };
  }
  // Từ không nháy dừng ở cả ký tự nối lệnh, để `node -e x;node -e …` vẫn thấy `node` thứ hai.
  // shortcut: từ ghép nhiều đoạn (`'x'"a;\nb"`) chỉ đo đoạn đầu; đủ cho cách viết thường gặp.
  let j = i;
  while (j < text.length && !isSpace(text[j])) j++;
  return { code: text.slice(i, j), end: j };
}

/** true nếu lệnh có `node -e`/`--eval` mà phần code nhiều dòng hoặc dài hơn MAX_INLINE ký tự. */
export function shouldBlock(command) {
  const text = command ?? "";
  NODE.lastIndex = 0;
  for (let m = NODE.exec(text); m; m = NODE.exec(text)) {
    let i = m.index + m[0].length;
    // Chỉ đi qua các tuỳ chọn có dấu gạch (ví dụ --input-type=module); gặp đối số khác thì dừng, nên
    // `node scripts/x.mjs | grep -e y` không khớp.
    for (;;) {
      while (i < text.length && isSpace(text[i])) i++;
      const start = i;
      while (i < text.length && !isSpace(text[i])) i++;
      if (text[start] !== "-") {
        i = start; // token này có thể chứa `;node` (ví dụ `x;node -e …`): để lần exec sau tìm trong nó
        break;
      }
      const token = text.slice(start, i);
      let codeStart = -1;
      if (token === "-e" || token === "--eval") {
        while (i < text.length && isSpace(text[i])) i++;
        codeStart = i;
      } else if (token.startsWith("--eval=")) {
        codeStart = start + "--eval=".length;
      }
      if (codeStart >= 0) {
        // shortcut: code lấy từ nơi khác (`-e "$(cat x.js)"`, heredoc `node <<EOF`) không bị đo; đủ cho lỗi mất escape đã gặp.
        const { code, end } = readWord(text, codeStart);
        if (tooLong(code)) return true;
        i = end; // code ngắn: quét tiếp phần sau, có thể còn một `node -e` khác trong cùng lệnh
        break;
      }
    }
    // Các `node` nằm trong tuỳ chọn vừa duyệt (ví dụ token `-;node`) không duyệt lại: giữ tổng công việc tuyến tính.
    NODE.lastIndex = Math.max(NODE.lastIndex, i);
  }
  return false;
}

function main() {
  let input;
  try {
    input = JSON.parse(readFileSync(0, "utf8"));
  } catch {
    return; // không đọc được input thì không chặn, để không làm hỏng mọi lệnh Bash
  }
  if (input.tool_name !== "Bash" || !shouldBlock(input.tool_input?.command)) return;
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: MESSAGE },
  }));
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();

