    ".github/workflows/ci-pr.yml": "# ci-pr: chạy trên mỗi PR nhắm vào main. 4 job độc lập, chạy song song.
# - backend-test: 447 unit test + AigameBackendApplicationTests (khởi động thật, chạy Flyway trên Supabase thật
#   của dự án — cần 5 secret bên dưới) + JaCoCo (chặn nếu LINE coverage < 70%, xem backend/pom.xml).
# - frontend-build: lint (oxlint) + test (Vitest) + build (gồm type-check TypeScript).
# - secret-scan: Gitleaks quét toàn bộ diff của PR, tìm secret bị commit nhầm.
# - docs-scripts: log AI không quá dài (xoay vòng bằng scripts/ai-log/rotate.mjs) và docs/openapi/INDEX.md còn mới.
#
# Còn thiếu so với sơ đồ CI/CD gốc (để làm sau, cần thêm tài khoản/hạ tầng):
# - SonarCloud (cần tài khoản) — khi có, gộp luôn phần "lint backend" vào đó.
# - Docker build, deploy staging/production — chưa có Dockerfile, chưa có server staging/production.

name: ci-pr

on:
  pull_request:
    branches: [main]

jobs:
  backend-test:
    name: Backend test (JDK 21)
    runs-on: ubuntu-latest
    defaults:
      run:
        working-directory: backend
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-java@v4
        with:
          distribution: temurin
          java-version: "21"
          cache: maven

      - name: Run tests (unit test + Layer 1-3 + khởi động thật trên Supabase)
        env:
          DB_URL: ${{ secrets.DB_URL }}
          DB_USERNAME: ${{ secrets.DB_USERNAME }}
          DB_PASSWORD: ${{ secrets.DB_PASSWORD }}
          JWT_SECRET: ${{ secrets.JWT_SECRET }}
          OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}
          PR_AUTHOR: ${{ github.event.pull_request.user.login }}
        # PR của Dependabot không nhận Actions secret nên không kết nối được Supabase; chỉ bỏ test khởi động thật,
        # không thêm secret DB cho Dependabot vì code của gói bên thứ ba chạy trong job này.
        run: |
          if [ "$PR_AUTHOR" = "dependabot[bot]" ]; then
            ./mvnw --batch-mode test '-Dtest=!AigameBackendApplicationTests' -Dsurefire.failIfNoSpecifiedTests=false
          else
            ./mvnw --batch-mode test
          fi

      - name: Upload JaCoCo coverage report
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: jacoco-report
          path: backend/target/site/jacoco
          retention-days: 14

  frontend-build:
    name: Frontend lint & build
    runs-on: ubuntu-latest
    defaults:
      run:
        working-directory: frontend
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: "24.22.1"
          cache: npm
          cache-dependency-path: frontend/package-lock.json

      - run: npm ci
      - run: npm run lint
      # Chỉ trên CI: giới hạn số luồng vitest (máy chạy CI ít nhân nên nhiều luồng làm test thời gian chập chờn, xem mục Nợ và rủi ro trong "docs/wiki/Kế hoạch và việc còn lại.md").
      # Chạy cục bộ vẫn dùng mặc định của vite.config.ts.
      - run: npm run test -- --maxWorkers=2
      - run: npm run build

  docs-scripts:
    name: Log AI và chỉ mục OpenAPI
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
