  auth:
    refresh-cookie:
      name: refresh_token
      path: /api/auth
      same-site: Strict
      # Secure cookies need HTTPS in production; browsers still accept them on http://localhost.
      secure: ${COOKIE_SECURE:true}
  assets:
    # Thử nghiệm: chữ nói tới hình A mà gắn hình B thì báo lỗi Layer 2 để AI sinh lại (retrieval + luật).
    meaning-check:
      enabled: ${ASSET_MEANING_CHECK_ENABLED:false}
    # Thử nghiệm: đưa các hình có từ khóa trong yêu cầu lên đầu danh mục trong prompt.
