    wording-review:
      enabled: ${WORDING_REVIEW_ENABLED:false}
  curriculum-rag:
    constraints-approved-sha256: ${CURRICULUM_CONSTRAINTS_APPROVED_SHA256:}
    enabled: ${CURRICULUM_RAG_ENABLED:false}
    embedding-model: ${GEMINI_EMBEDDING_MODEL:gemini-embedding-001}
    # Candidate floor for the deterministic Math Grade 1 path only; never a semantic acceptance gate.
